diff --git a/packages/request/src/context.ts b/packages/request/src/context.ts
index fefdd87..3d7a55a 100644
--- a/packages/request/src/context.ts
+++ b/packages/request/src/context.ts
@@ -1,3 +1,20 @@
 export type Headers = Readonly<Record<string, string | readonly string[] | undefined>>;
 export interface RequestContext { correlationId: string }
-export function createRequestContext(_headers: Headers, fallbackId: string): RequestContext { return {correlationId: fallbackId}; }
+
+const correlationIdPattern = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
+
+export function createRequestContext(headers: Headers, fallbackId: string): RequestContext {
+  const matchingKeys = Object.keys(headers).filter(key => key.toLowerCase() === 'x-correlation-id');
+  if (matchingKeys.length !== 1) return {correlationId: fallbackId};
+
+  const value = headers[matchingKeys[0]];
+  const rawValue = typeof value === 'string'
+    ? value
+    : Array.isArray(value) && value.length === 1
+      ? value[0]
+      : undefined;
+  if (typeof rawValue !== 'string') return {correlationId: fallbackId};
+
+  const correlationId = rawValue.trim();
+  return {correlationId: correlationIdPattern.test(correlationId) ? correlationId : fallbackId};
+}

