+}
+
+export function authenticate(token: Token, nowMs: number = Date.now(), clockSkewSeconds: number = 0) {
+  assertClock(nowMs, 'nowMs');
+  assertClock(clockSkewSeconds, 'clockSkewSeconds');
+
+  if (!validSubject(token)) throw new AuthError('Invalid token', 'invalid_token');
+
+  const {expiresAt} = token;
+  if (expiresAt !== undefined) {
+    if (!Number.isFinite(expiresAt) || expiresAt < 0) {
+      throw new AuthError('Invalid token', 'invalid_token');
+    }
+    if (nowMs >= (expiresAt + clockSkewSeconds) * 1000) {
+      throw new AuthError('Token expired', 'expired_token');
+    }
+  }
+
+  return {subject: token.subject};
+}
