import {expect,test} from 'vitest';
import {createCsvExporter} from './index.ts';
import type {CsvOptions} from './index.ts';

test('merges per-call options without mutating captured or call options',()=>{
 const captured: CsvOptions = {delimiter:';',newline:'\r\n',includeHeader:true};
 const perCall: CsvOptions = {delimiter:undefined,newline:undefined,includeHeader:false};
 const exporter = createCsvExporter(['name','value'],captured);
 expect(exporter([['Ada',0],['Bo',false]],perCall)).toBe('Ada;0\r\nBo;false');
 expect(captured).toEqual({delimiter:';',newline:'\r\n',includeHeader:true});
 expect(perCall).toEqual({delimiter:undefined,newline:undefined,includeHeader:false});
 expect(exporter([['Ada',0]])).toBe('name;value\r\nAda;0');
});

test('encodes headers and cells using the selected delimiter',()=>{
 const exporter = createCsvExporter(['first,name','say"what','line\nname']);
 expect(exporter([['a,b','say"yes','top\r\nbottom',null,undefined,0,false]],{delimiter:',',newline:'\n'}))
  .toBe('"first,name","say""what","line\nname"\n"a,b","say""yes","top\r\nbottom",,,0,false');
});

test('rejects invalid final delimiters and newlines',()=>{
 const exporter = createCsvExporter(['header']);
 for(const delimiter of ['', '"', '\r', '\n', 'ab']) expect(() => exporter([], {delimiter})).toThrow(RangeError);
 for(const newline of ['', '\r', '\n\n', '\r\n\n']) expect(() => exporter([], {newline})).toThrow(RangeError);
 expect(exporter([], {delimiter:'|',newline:'\r\n'})).toBe('header');
});
